import os 
import re
import cv2
import shutil
from tqdm import tqdm
from omnimedseg.utils.dataset_utils import *

def convert_coph100():
    copy_COph100_from_ROP()
    converted_path = os.path.join('datasets', 'Fundus', 'COPH100', 'converted')
    ensure_directories(converted_path, ['vessels'])
    idx = 0
    filename_map = {}
    extracted_base = os.path.join('datasets', 'Fundus', 'COPH100', 'extracted')
    image_paths = [os.path.join(extracted_base, f) for f in os.listdir(os.path.join(extracted_base)) if re.fullmatch(r'[\d\-]+', f)]

    for path in tqdm(sorted(image_paths), desc="🖼️  Processing COph100 images"):

        image_paths = [os.path.join(path, el) for el in os.listdir(path) if '.jpg' in el]
        for image_path in image_paths:
            filename = f"{idx:06d}.png"
            img = cv2.imread(image_path)
            label = cv2.imread(image_path.replace('.jpg', '_mask.png')).astype(np.uint8) * 255
            cv2.imwrite(os.path.join(converted_path, 'images', filename), img)
            cv2.imwrite(os.path.join(converted_path, 'labels', 'vessels', filename), label)
            filename_map[filename] = {'image': image_path, 'vessels': image_path.replace('.jpg', '_mask.png')}
            idx += 1
    save_mapping(converted_path, filename_map)


